{
  "title": "社内備品予約の基本設計書",
  "language": "ja",
  "background": [
    "紙台帳では同じ備品に重複する予約が入る。",
    "社員の予約・取消と、管理担当の貸出・返却を一つの仕組みで扱う。"
  ],
  "purpose": "開発者が責務・画面・データ・連携と理由を理解し、未決条件を確認して詳細設計へ進める。",
  "readers": [
    "開発者"
  ],
  "terms": [
    {
      "term": "予約の確定",
      "definition": "備品と時間帯を受け付け、重複する予約として扱われないよう登録した状態を指す。",
      "source_ids": [
        "SRC-01"
      ]
    }
  ],
  "scope": {
    "in": [
      "備品と時間帯を指定した予約と本人による取消",
      "管理担当による貸出・返却の記録",
      "予約確定後のメール通知"
    ],
    "out": [
      "対象外の業務は未指定。「今回扱わない業務の範囲」で確認する。"
    ]
  },
  "actors": [
    {
      "id": "ACT-01",
      "name": "社員",
      "role": "備品と日時を選んで申し込み、自分の予約を取り消す。",
      "source_ids": [
        "SRC-01"
      ]
    },
    {
      "id": "ACT-02",
      "name": "管理担当",
      "role": "備品の貸出と返却を記録する。",
      "source_ids": [
        "SRC-01"
      ]
    }
  ],
  "requirements": [
    {
      "id": "REQ-01",
      "title": "備品を予約して重複を防ぐ",
      "statement": "社員は備品と開始・終了日時を指定して申し込み、重複する時間帯の予約を確定させない。",
      "source_ids": [
        "SRC-01"
      ]
    },
    {
      "id": "REQ-02",
      "title": "自分の予約を取り消す",
      "statement": "社員は自分の予約を取り消せる。",
      "source_ids": [
        "SRC-01"
      ]
    },
    {
      "id": "REQ-03",
      "title": "貸出と返却を記録する",
      "statement": "管理担当は備品の貸出と返却を記録する。",
      "source_ids": [
        "SRC-01"
      ]
    },
    {
      "id": "REQ-04",
      "title": "予約確定を本人へ通知する",
      "statement": "予約確定後、既存の社内メール基盤から本人へ通知する。",
      "source_ids": [
        "SRC-01"
      ]
    }
  ],
  "coverage": [
    {
      "area": "architecture",
      "applicable": true,
      "reason": "受付判定・保存・画面・メールの責務を分けて、重複防止と通知の順序を説明する。",
      "source_ids": [
        "SRC-01"
      ],
      "question_ids": []
    },
    {
      "area": "screen",
      "applicable": true,
      "reason": "社員の予約・取消と管理担当の貸出・返却を、目的別の操作として説明する。",
      "source_ids": [
        "SRC-01"
      ],
      "question_ids": []
    },
    {
      "area": "data",
      "applicable": true,
      "reason": "社員・備品・予約・利用記録の関係と、重複を判定する情報を説明する。",
      "source_ids": [
        "SRC-01"
      ],
      "question_ids": []
    },
    {
      "area": "integration",
      "applicable": true,
      "reason": "既存メール基盤への依頼と、失敗時に未決の条件を説明する。",
      "source_ids": [
        "SRC-01"
      ],
      "question_ids": []
    }
  ],
  "designs": [
    {
      "id": "DES-01",
      "area": "architecture",
      "title": "予約の判定と登録を一つの責務へ集める",
      "statement": "画面から予約受付を呼び出し、同じ備品への重複の判定と登録を一つの単位で扱う設計案とする。",
      "reason": "画面ごとに判定が分かれることを避け、重複する予約を確定させないため。",
      "details": [
        "社員の申込み・取消と管理担当の貸出・返却は、予約受付へ集める。",
        "既存メール基盤への依頼は、予約の登録完了後に行う。",
        "同時申込みの採否を決める順序と、境界時刻の扱いは詳細設計で確認する。"
      ],
      "status": "proposal",
      "requirement_ids": [
        "REQ-01",
        "REQ-02",
        "REQ-03",
        "REQ-04"
      ],
      "source_ids": [
        "SRC-01"
      ],
      "diagram_ids": [
        "D-01",
        "D-02",
        "D-03"
      ],
      "question_ids": [
        "Q-06"
      ]
    },
    {
      "id": "DES-02",
      "area": "screen",
      "title": "目的別に画面と操作を分ける",
      "statement": "社員には備品一覧・予約入力・結果確認・自分の予約一覧を示し、管理担当には貸出・返却の一覧を設ける案とする。",
      "reason": "社員が自分の申込みと取消を確認でき、管理担当の記録操作と区別できるため。",
      "details": [
        "予約入力は備品、開始日時、終了日時を受け取る。",
        "重複する予約は確定させず、結果確認で重複を伝える。",
        "本人の取消は自分の予約一覧から行う。受付期限は「取消期限」で確認する。",
        "管理担当は貸出・返却の一覧から利用記録を更新する。"
      ],
      "status": "proposal",
      "requirement_ids": [
        "REQ-01",
        "REQ-02",
        "REQ-03"
      ],
      "source_ids": [
        "SRC-01"
      ],
      "diagram_ids": [
        "D-04"
      ],
      "question_ids": [
        "Q-01"
      ]
    },
    {
      "id": "DES-03",
      "area": "data",
      "title": "予約と利用記録を分けて保持する",
      "statement": "予約を社員と備品へ関連付け、貸出と返却は予約に対応する利用記録として保持する案とする。",
      "reason": "重複の判定に使う予約と、実際の貸出・返却の履歴を別の目的で扱うため。",
      "details": [
        "予約は申込者・備品・開始日時・終了日時・状態を持つ。",
        "社員1人と備品1点に対し、それぞれ複数の予約が対応する。",
        "予約の状態は確定・取消を扱い、利用記録に貸出・返却を残す。",
        "予約受付で同じ備品の重複判定と登録を一つの単位として扱い、物理制約は詳細設計へ渡す。"
      ],
      "status": "proposal",
      "requirement_ids": [
        "REQ-01",
        "REQ-02",
        "REQ-03"
      ],
      "source_ids": [
        "SRC-01"
      ],
      "diagram_ids": [
        "D-05",
        "D-07"
      ],
      "question_ids": [
        "Q-06"
      ]
    },
    {
      "id": "DES-04",
      "area": "integration",
      "title": "確定した予約を既存メールへ渡す",
      "statement": "予約の登録が完了してから、本人の通知先と予約内容を既存メール基盤へ渡す案とする。",
      "reason": "未確定の予約を確定通知として送らず、要望にある既存の通知経路を使うため。",
      "details": [
        "正常時は登録完了、送信依頼、結果確認の順とする。",
        "接続方式と送信結果の形式は利用技術と合わせて確認する。",
        "送信失敗時の再送と予約結果への影響は未決であり、「メール送信失敗時の扱い」で確認する。"
      ],
      "status": "proposal",
      "requirement_ids": [
        "REQ-04"
      ],
      "source_ids": [
        "SRC-01"
      ],
      "diagram_ids": [
        "D-06"
      ],
      "question_ids": [
        "Q-02",
        "Q-03"
      ]
    },
    {
      "id": "DES-05",
      "area": "architecture",
      "title": "利用する技術を既存環境と合わせて選ぶ",
      "statement": "既存の実行環境と運用の条件を確認してから、保存先と受付処理の実装技術を決める。",
      "reason": "利用技術が会話に指定されておらず、採用済みの製品として確定できないため。",
      "details": [
        "ここに示す責務の分担は製品の採用を意味しない。"
      ],
      "status": "open",
      "requirement_ids": [
        "REQ-01",
        "REQ-04"
      ],
      "source_ids": [
        "SRC-01"
      ],
      "diagram_ids": [
